--region handler
function AccusationFillDetailsNode:OnBtnSendReport()
    local t = {}
    for k, v in pairs(self._reasons) do
        if v.isChecked then
            table.insert(t, k)
        end
    end
    table.sort(t, function(a, b)
        return checkNumber(a) < checkNumber(b)
    end)
    local sendListStr = table.concat(t,",")
    local detailsText = self.TextInput.text
    --printInfo(sendListStr)
    --printInfo(detailsText)
    --printInfo(checkString(self._targetPlayerId))
    local jsonDateReq = {
        reportedPlayerId = checkNumber(self._targetPlayerId),
        type = checkString(sendListStr),
        details = checkString(detailsText),
        chatMessage = checkString(self._targetMessage)
    }
    GameUtils.Request(Interfaces.OverseaAccusePlayer, jsonDateReq, function(request, response)
        if checkNumber(response.errCode) ~= 0 then
            return
        end
        GameUtils.Toast(localize("举报成功"))
        UIModule.BackDialog()
    end)
end

function AccusationFillDetailsNode:OnBtnLastStep()
    self._comp:SwitchStatus()
end

function AccusationFillDetailsNode:OnUpdateCellHandler(cellInfo)
    self._reasons[checkString(cellInfo.id)] = cellInfo

    self._resultText = ""
    for k, v in pairs(self._reasons) do
        if v.isChecked then
            self._resultText = self._resultText .. v.text .. ","
        end
    end
end
--endregion handler

